/**
 * Level B `/t/$` route — thin-handler contract (TDD).
 *
 * The pure addressing + verification (`parseDevThemeAssetPath`,
 * `resolveDevThemeAsset`) is pinned by `dev-theme-asset-serve.test.ts`.
 * This suite pins the glue the route file owns: splat extraction, the
 * three exact-name store reads, and the Response mapping (verified bytes
 * with immutable caching; every refusal 404 with `no-store`, never an
 * immutable directive on a refusal).
 *
 * NOTE: `src/routeTree.gen.ts` is auto-generated by the TanStack vite
 * plugin on dev/build and is untouched here, so the static route id is
 * captured through a `createFileRoute` mock — the file's runtime shape
 * (server GET handler) is what is exercised.
 */
import { describe, expect, it, vi, beforeEach } from "vitest";
import { fakeDb } from "@/lib/__fixtures__/fake-db";
import {
  metricRecorder,
  allowAllRateLimits,
} from "@/lib/__fixtures__/test-doubles";
import {
  createDevThemeReleaseStore,
  type DevThemeRelease,
} from "@/lib/dev-theme-review";
import {
  validateDevThemeBundle,
  type DevThemeBundleInput,
} from "@/lib/dev-theme-bundle";
import { DEV_THEME_RUNTIME_VERSION } from "@/lib/dev-theme-manifest";

type Recorder = ReturnType<typeof metricRecorder>;
const rec = vi.hoisted(() => ({ holder: null as Recorder | null }));
const dbHolder = vi.hoisted(() => ({
  db: null as ReturnType<typeof fakeDb> | null,
}));
const recorder = metricRecorder();
rec.holder = recorder;

vi.mock("@/lib/observability.server", () => rec.holder!.observability);
vi.mock("@/lib/rate-limit.server", () => allowAllRateLimits());
vi.mock("@tanstack/react-router", () => ({
  createFileRoute:
    (id: string) =>
    (config: {
      server: {
        handlers: Record<string, (args: unknown) => Promise<Response>>;
      };
    }) => ({ routeId: id, handlers: config.server.handlers }),
}));
vi.mock("@/lib/pricing.server", () => ({
  publicClient: () => dbHolder.db!.asClient(),
}));

const { installReviewedThemeBundle } =
  await import("@/lib/dev-theme-bundle-install");
const { Route } = await import("./t.$");

const MERCHANT = "22222222-2222-2222-2222-222222222222";
const SELLER = "11111111-1111-1111-1111-111111111111";
const ACTOR = "99999999-9999-4999-8999-999999999999";
const LISTING_ID = "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa";
const THEME_SLUG = "aurora-lookbook";
const T0 = "2026-10-01T00:00:00.000Z";
const T1 = "2026-10-02T00:00:00.000Z";
const MOD = { id: "reviewer-1", role: "moderator" } as const;
const GSAP_DEP = {
  name: "gsap",
  version: "3.15.0",
  license: "MIT",
  integrity: "sha384-AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=",
};

const HERO_JS = `export function HeroCanvas(el, props) { el.textContent = props.headline; }`;

function manifest(): Record<string, unknown> {
  return {
    id: THEME_SLUG,
    version: "1.0.0",
    runtime: DEV_THEME_RUNTIME_VERSION,
    name: "Aurora Lookbook",
    publisher: "Studio Framique",
    capabilities: ["presentation"],
    dependencies: [{ ...GSAP_DEP }],
    sections: [{ key: "hero", slot: "main", component: "HeroCanvas" }],
    settings: [{ key: "headline", label: "Headline", type: "text" }],
  };
}

function bundleInput(): DevThemeBundleInput {
  const m = manifest();
  return {
    manifest: m,
    files: [
      {
        path: "dev.theme.json",
        bytes: new TextEncoder().encode(JSON.stringify(m)),
      },
      { path: "components/Hero.js", bytes: new TextEncoder().encode(HERO_JS) },
    ],
    dependencies: [{ ...GSAP_DEP }],
    allowedNetworkHosts: [],
  };
}

async function installedDb() {
  const db = fakeDb({
    tables: {
      marketplace_themes: [],
      marketplace_installs: [],
      store_themes: [],
      theme_versions: [],
      theme_drafts: [],
      activity_log: [],
      theme_audit: [],
      wallet_ledger_entries: [],
      theme_assets: [],
    },
  });
  const store = createDevThemeReleaseStore();
  const v = validateDevThemeBundle(bundleInput());
  expect(v.ok).toBe(true);
  if (!v.ok) throw new Error("fixture bundle rejected");
  const { release: submitted } = store.submit({
    merchantId: SELLER,
    themeId: THEME_SLUG,
    manifest: v.manifest,
    files: v.files,
    fingerprint: v.fingerprint,
    submittedBy: "dev-1",
    submittedAt: T0,
  });
  store.review({
    releaseId: submitted.id,
    merchantId: SELLER,
    reviewer: { ...MOD },
    decision: "approve",
    reason: "clean",
    reviewedAt: T1,
  });
  const { release } = store.publish({
    releaseId: submitted.id,
    merchantId: SELLER,
    actor: { ...MOD },
    expectedFingerprint: v.fingerprint,
    publishedAt: T1,
  });
  await installReviewedThemeBundle(db.asClient(), MERCHANT, {
    release: release as DevThemeRelease,
    bytes: bundleInput(),
    idempotencyKey: "dev-route-1",
    listing: {
      id: LISTING_ID,
      slug: THEME_SLUG,
      name: "Aurora Lookbook",
      version: "1.0.0",
      price_minor_int: 0,
      currency_code: "BDT",
      seller_merchant_id: SELLER,
      install_count: 0,
    },
    trial: false,
    consentedBy: ACTOR,
    expectedThemeId: THEME_SLUG,
  });
  return db;
}

async function get(splat: string): Promise<Response> {
  const handlers = (
    Route as unknown as {
      handlers: Record<string, (args: unknown) => Promise<Response>>;
    }
  ).handlers;
  return handlers.GET({
    request: new Request(`https://shop.example/t/${splat}`),
    params: { _splat: splat },
  });
}

beforeEach(() => recorder.reset());

describe("/t/$ handler", () => {
  it("serves verified bytes with immutable caching", async () => {
    dbHolder.db = await installedDb();
    const assets = dbHolder.db.rows("theme_assets") as { name: string }[];
    const js = assets.find((a) => a.name.endsWith(".js"))!;
    const splat = js.name.replace("dev-themes/", "");
    const res = await get(splat);
    expect(res.status).toBe(200);
    expect(res.headers.get("content-type")).toContain("javascript");
    expect(res.headers.get("x-content-type-options")).toBe("nosniff");
    expect(res.headers.get("cache-control")).toBe(
      "public, max-age=31536000, immutable",
    );
    expect(await res.text()).toBe(HERO_JS);
  });

  it("refuses traversal, unknown versions, and index.html with no-store 404s", async () => {
    dbHolder.db = await installedDb();
    for (const splat of [
      "aurora-lookbook/1.0.0/../secret",
      "aurora-lookbook/1.0.0/%2e%2e/secret",
      "aurora-lookbook/9.9.9/components/Hero.js",
      "aurora-lookbook/1.0.0/index.html",
      "aurora-lookbook/latest/components/Hero.js",
    ]) {
      const res = await get(splat);
      expect(`${splat}: ${res.status}`).toBe(`${splat}: 404`);
      expect(res.headers.get("cache-control")).toBe("no-store");
    }
  });
});
